Hi! I have a documentation issue on InstantSearch.js, I could not find what I was looking for which is:
I have 10 categories onn the left side and i would like to show 3 specific categories on the left side category section. Anyidea how i can pass the list to display on the left side?
I would like to display "Beers", "cider", and "howlers" on this list only and not every category that  i have.
/\* Categories refinement widget \*/
search.addWidget(
instantsearch.widgets.refinementList({
container: '#facet-categories',
attributeName: 'taxonomies\_hierarchical.product\_cat.lvl0',
separator: ' > ',
sortBy: \['count:desc', 'name:asc'],
'taxonomies\_hierarchical.product\_cat.lvl1', 'taxonomies\_hierarchical.product\_cat.lvl2'],
templates: {
header: '<h4>' + algolia.woocommerce.i18n.product\_categories + '</h4>'
}
})
);
